// Click-fraud check for the real-time ad-click aggregator.
// Consumes click events off the ingestion stream/queue and flags abusive IPs.

interface ClickEvent {
  ip: string;
  adId: string;
  timestamp: number;
}

const FRAUD_THRESHOLD = 100;

// Per-IP click tally. Created once when the consumer module loads.
const clickCounts = new Map<string, number>();

// IPs that have been flagged as fraudulent so far.
const flaggedIps = new Set<string>();

function blockIp(ip: string): void {
  flaggedIps.add(ip);
  console.warn(`[fraud] blocked ip=${ip}`);
}

function emitFraudAlert(ip: string, totalClicks: number): void {
  console.warn(`[fraud] alert ip=${ip} totalClicks=${totalClicks}`);
}

/**
 * Stream/queue consumer callback invoked for every incoming click event.
 */
export function processClick(event: ClickEvent): void {
  const ip = event.ip;

  clickCounts.set(ip, (clickCounts.get(ip) ?? 0) + 1);

  const total = clickCounts.get(ip) ?? 0;
  if (total > FRAUD_THRESHOLD) {
    blockIp(ip);
    emitFraudAlert(ip, total);
  }
}
